extends Node

@onready var animation_tree: AnimationTree = $"../AnimationTree"
@onready var state_machine: AnimationNodeStateMachinePlayback = animation_tree.get("parameters/playback")

func set_move_input(input_vec: Vector2) -> void:
    animation_tree.set("parameters/Locomotion/blend_position", input_vec)

func trigger_attack() -> void:
    animation_tree.set("parameters/conditions/condition_attack", true)
    # The machine handles the transition based on this condition.
    # Note: We need to reset the condition after the transition or during.
    # Usually, for a state machine, the transition sets the condition back to false if set up right, 
    # but let's just make it a trigger.
    await get_tree().process_frame
    animation_tree.set("parameters/conditions/condition_attack", false)

func current_state() -> StringName:
    return state_machine.get_current_node()

extends Node

@onready var animation_tree: AnimationTree = $"../AnimationTree"
@onready var animation_player: AnimationPlayer = $"../AnimationPlayer"

func _ready():
    _setup_tree()

func _setup_tree():
    var state_machine = AnimationNodeStateMachine.new()
    animation_tree.tree_root = state_machine

    # Locomotion
    var locomotion = AnimationNodeBlendSpace2D.new()
    locomotion.add_blend_point(AnimationNodeAnimation.new(), Vector2(0, 0), 0) # idle
    # Cardinal walks
    locomotion.add_blend_point(AnimationNodeAnimation.new(), Vector2(0, -1), 1) # north
    locomotion.add_blend_point(AnimationNodeAnimation.new(), Vector2(0, 1), 2)  # south
    locomotion.add_blend_point(AnimationNodeAnimation.new(), Vector2(1, 0), 3)  # east
    locomotion.add_blend_point(AnimationNodeAnimation.new(), Vector2(-1, 0), 4) # west

    # Actually, we need to set the animation name for each point.
    # The nodes are AnimationNodeAnimation.
    (locomotion.get_blend_point_node(0) as AnimationNodeAnimation).animation = &"idle"
    (locomotion.get_blend_point_node(1) as AnimationNodeAnimation).animation = &"walk_north"
    (locomotion.get_blend_point_node(2) as AnimationNodeAnimation).animation = &"walk_south"
    (locomotion.get_blend_point_node(3) as AnimationNodeAnimation).animation = &"walk_east"
    (locomotion.get_blend_point_node(4) as AnimationNodeAnimation).animation = &"walk_west"

    state_machine.add_node("Locomotion", locomotion)

    # Attack
    var attack = AnimationNodeAnimation.new()
    attack.animation = &"attack"
    state_machine.add_node("Attack", attack)

    # Transitions
    state_machine.add_transition("Locomotion", "Attack", "condition_attack")

    var t = AnimationNodeStateMachineTransition.new()
    t.switch_mode = AnimationNodeStateMachineTransition.SWITCH_MODE_AT_END
    state_machine.add_transition("Attack", "Locomotion", t)

    animation_tree.anim_player = animation_player.get_path()

@onready var state_machine_playback: AnimationNodeStateMachinePlayback = animation_tree.get("parameters/playback")

func set_move_input(input_vec: Vector2) -> void:
    animation_tree.set("parameters/Locomotion/blend_position", input_vec)

func trigger_attack() -> void:
    animation_tree.set("parameters/conditions/condition_attack", true)
    await get_tree().process_frame
    animation_tree.set("parameters/conditions/condition_attack", false)

func current_state() -> StringName:
    return state_machine_playback.get_current_node()

extends Node

@onready var animation_tree: AnimationTree = $"../AnimationTree"
@onready var animation_player: AnimationPlayer = $"../AnimationPlayer"

func _ready():
    _create_animations()
    _setup_tree()

func _create_animations():
    var anim_names = ["idle", "walk_north", "walk_south", "walk_east", "walk_west", "attack"]
    var library = AnimationLibrary.new()
    for name in anim_names:
        var anim = Animation.new()
        anim.length = 1.0
        anim.add_track(Animation.TYPE_VALUE)
        anim.track_set_path(0, ".:position")
        library.add_animation(name, anim)
    animation_player.add_animation_library("", library)

func _setup_tree():
    var state_machine = AnimationNodeStateMachine.new()
    animation_tree.tree_root = state_machine

    # Locomotion
    var locomotion = AnimationNodeBlendSpace2D.new()
    # The order of add_blend_point matters.
    # idle: (0,0), north: (0,-1), south: (0,1), east: (1,0), west: (-1,0)

    var anim_names = ["idle", "walk_north", "walk_south", "walk_east", "walk_west"]
    var positions = [Vector2(0,0), Vector2(0,-1), Vector2(0,1), Vector2(1,0), Vector2(-1,0)]

    for i in range(len(anim_names)):
        var node = AnimationNodeAnimation.new()
        node.animation = StringName(anim_names[i])
        locomotion.add_blend_point(node, positions[i], i)

    state_machine.add_node("Locomotion", locomotion)

    # Attack
    var attack = AnimationNodeAnimation.new()
    attack.animation = &"attack"
    state_machine.add_node("Attack", attack)

    # Transitions
    var t1 = AnimationNodeStateMachineTransition.new()
    t1.advance_mode = AnimationNodeStateMachineTransition.ADVANCE_MODE_CONDITIONAL
    t1.advance_condition = &"condition_attack"
    state_machine.add_transition("Locomotion", "Attack", t1)

    var t2 = AnimationNodeStateMachineTransition.new()
    t2.switch_mode = AnimationNodeStateMachineTransition.SWITCH_MODE_AT_END
    state_machine.add_transition("Attack", "Locomotion", t2)

    animation_tree.anim_player = animation_player.get_path()
    animation_tree.active = true # Must be active for playback

@onready var state_machine_playback: AnimationNodeStateMachinePlayback = animation_tree.get("parameters/playback")

func set_move_input(input_vec: Vector2) -> void:
    animation_tree.set("parameters/Locomotion/blend_position", input_vec)

func trigger_attack() -> void:
    animation_tree.set("parameters/conditions/condition_attack", true)
    # The transition occurs immediately, and at the end of the attack, it goes back.
    # To avoid getting stuck in the attack state, we reset the condition.
    # Actually, the condition needs to be reset after the state transition *starts*.
    await get_tree().create_timer(0.1).timeout
    animation_tree.set("parameters/conditions/condition_attack", false)

func current_state() -> StringName:
    return state_machine_playback.get_current_node()
